const fs = require\('fs'\);
const collection = JSON.parse\(fs.readFileSync\('tindao.postman_collection.json', 'utf8'\)\);

const eventsFolder = collection.item.find\(f => f.name === 'Events'\);

// Find the position of 'Cancel Event' to insert 'Publish Event' before it
const cancelIdx = eventsFolder.item.findIndex\(i => i.name === 'Cancel Event'\);

const publishRequest = {
  name: 'Publish Event',
  request: {
    method: 'PATCH',
    header: [],
    url: {
      raw: '{{baseUrl}}/v1/events/{{eventId}}/publish',
      host: ['{{baseUrl}}'],
      path: ['v1', 'events', '{{eventId}}', 'publish']
    },
    description: 'Publish a draft event \(organizer only\). Moves status from DRAFT to PUBLISHED, making it visible in public listings.'
  },
  response: []
};

eventsFolder.item.splice\(cancelIdx, 0, publishRequest\);

fs.writeFileSync\('tindao.postman_collection.json', JSON.stringify\(collection, null, 2\)\);
console.log\('Publish Event inserted at index', cancelIdx\);
")

