const fs = require\('fs'\);
const data = JSON.parse\(fs.readFileSync\('C:/Users/Breno/Documents/projetos/tindao-backend/tindao.postman_collection.json'\)\);

const eventsFolder = data.item.find\(i => i.name === 'Events'\);
const subEventsFolder = eventsFolder.item.find\(i => i.name === 'Sub-events'\);

// Add Delete Event
eventsFolder.item.push\({
    name: 'Delete Event',
    request: {
        method: 'DELETE',
        header: [{ key: 'Authorization', value: 'Bearer {{accessToken}}' }],
        url: {
            raw: '{{baseUrl}}/v1/events/{{eventId}}',
            host: ['{{baseUrl}}'],
            path: ['v1', 'events', '{{eventId}}']
        },
        description: 'Soft delete an event. Owner or admin only. Cascades to all sub-events.'
    },
    response: []
}\);

// Add Delete Sub-Event
subEventsFolder.item.push\({
    name: 'Delete Sub-Event',
    request: {
        method: 'DELETE',
        header: [{ key: 'Authorization', value: 'Bearer {{accessToken}}' }],
        url: {
            raw: '{{baseUrl}}/v1/events/{{eventId}}/sub-events/{{subEventId}}',
            host: ['{{baseUrl}}'],
            path: ['v1', 'events', '{{eventId}}', 'sub-events', '{{subEventId}}']
        },
        description: 'Soft delete a sub-event. Allowed for: sub-event creator, parent event organizer, or admin.'
    },
    response: []
}\);

fs.writeFileSync\('C:/Users/Breno/Documents/projetos/tindao-backend/tindao.postman_collection.json', JSON.stringify\(data, null, 2\)\);
console.log\('Done'\);
console.log\('Events:', eventsFolder.item.map\(i => i.name\)\);
console.log\('Sub-events:', subEventsFolder.item.map\(i => i.name\)\);
")
